
from flask import Flask, render_template_string, jsonify
app = Flask(__name__)

QUESTIONS = [
("easy","He likes math, ____ he practices it every day.",["However","So","Otherwise","Although"],"So","Cậu ấy thích Toán, vì vậy cậu ấy luyện tập mỗi ngày.","So nêu kết quả."),
("easy","She was tired, ____ she went to bed early.",["so","but","although","or"],"so","Cô ấy mệt, vì vậy cô ấy đi ngủ sớm.","So nêu kết quả."),
("easy","I stayed home ____ I was sick.",["but","because","so","or"],"because","Tôi ở nhà vì tôi bị ốm.","Because nêu nguyên nhân."),
("easy","Would you like tea ____ coffee?",["and","but","or","so"],"or","Bạn muốn trà hay cà phê?","Or đưa ra lựa chọn."),
("easy","Lan likes English ____ she likes science, too.",["and","otherwise","although","because"],"and","Lan thích tiếng Anh và cũng thích khoa học.","And thêm thông tin."),
("easy","It was cold, ____ we wore jackets.",["but","so","although","however"],"so","Trời lạnh, vì vậy chúng tôi mặc áo khoác.","So nêu kết quả."),
("easy","He is young, ____ he is very responsible.",["because","but","so","therefore"],"but","Cậu ấy còn trẻ, nhưng rất có trách nhiệm.","But nối ý tương phản."),
("easy","____ it was raining, we stayed inside.",["Because","But","So","Or"],"Because","Vì trời mưa nên chúng tôi ở trong nhà.","Because nêu lý do."),
("medium","It was raining. ____, we still went for a walk.",["Therefore","However","So","Because"],"However","Trời mưa. Tuy nhiên, chúng tôi vẫn đi dạo.","However diễn tả tương phản."),
("medium","Tom studied hard. ____, he passed the exam.",["Although","Therefore","But","Otherwise"],"Therefore","Tom học chăm chỉ. Vì vậy, cậu ấy vượt qua kỳ thi.","Therefore nêu kết quả."),
("medium","Hurry up; ____, you will miss the bus.",["however","otherwise","therefore","because"],"otherwise","Nhanh lên; nếu không, bạn sẽ lỡ xe buýt.","Otherwise nghĩa là nếu không thì."),
("medium","____ she was nervous, she gave a good presentation.",["Although","Therefore","So","Because"],"Although","Mặc dù lo lắng, cô ấy vẫn thuyết trình tốt.","Although nghĩa là mặc dù."),
("medium","The shop was closed; ____, we went somewhere else.",["however","therefore","although","but"],"therefore","Cửa hàng đóng cửa; vì vậy, chúng tôi đi nơi khác.","Therefore nêu kết quả."),
("medium","You can take the train, ____ you can go by bus.",["or","because","however","therefore"],"or","Bạn có thể đi tàu hoặc xe buýt.","Or đưa ra lựa chọn."),
("medium","Mai wanted to play outside, ____ she had to finish homework first.",["so","but","therefore","because"],"but","Mai muốn chơi, nhưng phải làm xong bài tập trước.","But nối ý tương phản."),
("medium","I was hungry, ____ I made a sandwich.",["so","although","however","otherwise"],"so","Tôi đói, vì vậy tôi làm bánh mì kẹp.","So nêu kết quả."),
("hard","The road was flooded. ____, the school postponed the trip.",["Nevertheless","Therefore","Although","Otherwise"],"Therefore","Đường bị ngập. Vì vậy, trường hoãn chuyến đi.","Therefore nêu kết quả."),
("hard","He had little time; ____, he completed the task carefully.",["therefore","nevertheless","because","otherwise"],"nevertheless","Cậu ấy có ít thời gian; tuy vậy, cậu ấy hoàn thành nhiệm vụ.","Nevertheless nghĩa là tuy vậy."),
("hard","You must save your work; ____, you may lose your changes.",["otherwise","however","therefore","although"],"otherwise","Bạn phải lưu bài; nếu không, bạn có thể mất thay đổi.","Otherwise nêu hậu quả."),
("hard","____ the weather was terrible, the event continued as planned.",["Despite","Although","Therefore","So"],"Although","Mặc dù thời tiết tệ, sự kiện vẫn tiếp tục.","Although đi với mệnh đề."),
("hard","The instructions were unclear. ____, several students made mistakes.",["Consequently","However","Although","Nevertheless"],"Consequently","Hướng dẫn không rõ. Do đó, vài học sinh mắc lỗi.","Consequently nghĩa là do đó."),
("hard","She practiced every day; ____, her pronunciation improved.",["as a result","on the other hand","otherwise","although"],"as a result","Cô ấy luyện tập mỗi ngày; kết quả là phát âm tiến bộ.","As a result giới thiệu kết quả."),
("hard","I like the design. ____, it is too expensive for me.",["Therefore","Moreover","However","Consequently"],"However","Tôi thích thiết kế này. Tuy nhiên, nó quá đắt.","However nêu ý trái ngược."),
("hard","Bring a map; ____, you might get lost.",["otherwise","therefore","nevertheless","because"],"otherwise","Hãy mang bản đồ; nếu không, bạn có thể bị lạc.","Otherwise nêu hậu quả.")
]
BANK = [{"level":l,"q":q,"options":o,"answer":a,"meaning":m,"explain":e} for l,q,o,a,m,e in QUESTIONS]
CONNECTORS = [
("However","tuy nhiên","Diễn tả sự tương phản."),("Therefore","do đó / vì vậy","Nêu kết quả hoặc kết luận."),
("Otherwise","nếu không thì","Nêu hậu quả nếu không làm điều được nhắc đến."),("But","nhưng","Nối hai ý tương phản."),
("So","vì vậy / nên","Nêu kết quả."),("Because","bởi vì","Nêu nguyên nhân."),
("Although","mặc dù","Nêu sự tương phản; theo sau là một mệnh đề."),("And","và","Thêm thông tin."),
("Or","hoặc / hay","Đưa ra lựa chọn."),("Nevertheless","tuy vậy","Nêu sự tương phản."),
("As a result","kết quả là","Giới thiệu kết quả."),("Consequently","do đó / vì thế","Nêu kết quả.")
]

HTML = """<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>English Connectors 5.0</title>
<style>
:root{--bg:#0b1020;--p:#151d33;--p2:#1c2945;--t:#eef3ff;--m:#aab8d4;--a:#8da8ff;--g:#48d6a0;--r:#ff7b8b;--line:#2b3958}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#20365c,#0b1020 58%);font-family:system-ui,Arial,sans-serif;color:var(--t);min-height:100vh}.wrap{max-width:960px;margin:auto;padding:18px 14px 45px}
header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.brand{display:flex;align-items:center;gap:10px}.logo{background:linear-gradient(135deg,#8da8ff,#71e2d0);color:#091225;border-radius:14px;padding:10px 15px;font-size:25px;font-weight:900}.eyebrow{font-size:11px;letter-spacing:2px;color:#a9bcff;font-weight:800}h1{font-size:clamp(23px,5vw,32px);margin:2px 0}.version,.pill{border:1px solid #45567c;border-radius:999px;padding:6px 10px;color:#c9d6ff;font-size:12px;font-weight:800}
.hero{padding:24px 0 12px}.hero h2{font-size:clamp(28px,6vw,42px);line-height:1.12;margin:5px 0 12px}.hero p,.muted{color:var(--m);line-height:1.6}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.stat,.panel{background:rgba(21,29,51,.95);border:1px solid var(--line);border-radius:18px}.stat{padding:13px}.stat strong{display:block;font-size:23px}.stat span,.small{font-size:13px;color:var(--m);line-height:1.5}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.tab,.btn{border:1px solid #405277;background:#17233c;color:var(--t);border-radius:12px;padding:10px 13px;font-weight:750;cursor:pointer}.tab.active,.primary{background:var(--a);border-color:var(--a);color:#091225}.btn:disabled{opacity:.4;cursor:not-allowed}.panel{padding:clamp(15px,3vw,23px);margin:12px 0}.hidden{display:none!important}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.between{justify-content:space-between}.select{background:#10192c;border:1px solid #405277;color:var(--t);padding:10px 12px;border-radius:10px;font:inherit}.progress{height:7px;background:#293754;border-radius:999px;overflow:hidden;margin:12px 0 19px}.bar{height:100%;width:0;background:linear-gradient(90deg,#8da8ff,#71e2d0);transition:width .2s}.q{font-size:clamp(20px,4vw,27px);font-weight:800;line-height:1.4;margin:20px 0}.options{display:grid;grid-template-columns:1fr 1fr;gap:10px}.opt{background:var(--p2);color:var(--t);border:1px solid #354568;border-radius:13px;padding:14px;text-align:left;font-size:16px;cursor:pointer}.opt.selected{border-color:var(--a);outline:2px solid #8da8ff33}.opt.correct{border-color:var(--g);background:#123a35}.opt.wrong{border-color:var(--r);background:#412331}.controls{display:flex;gap:9px;flex-wrap:wrap;margin-top:17px}.feedback{padding:14px;border-radius:13px;margin-top:15px;line-height:1.6}.good{background:#123a35;border:1px solid #26745d}.bad{background:#412331;border:1px solid #8b4555}.scorebig{font-size:34px;font-weight:900}.connector{display:grid;grid-template-columns:145px 1fr;gap:12px;padding:14px 0;border-bottom:1px solid #2c3855}.word{font-size:18px;font-weight:850;color:#a9bcff}.translation{font-weight:750;margin-bottom:4px}.history-item{padding:12px 0;border-bottom:1px solid #2c3855}.empty{text-align:center;padding:22px;color:var(--m)}
@media(max-width:560px){.options{grid-template-columns:1fr}.connector{grid-template-columns:1fr;gap:4px}.stat{padding:10px}.stat strong{font-size:20px}}
</style></head><body><main class="wrap">
<header><div class="brand"><div class="logo">E</div><div><div class="eyebrow">LEARN • PRACTICE • IMPROVE</div><h1>English Connectors</h1></div></div><span class="version">VERSION 5.0</span></header>
<div class="hero"><h2>Chinh phục từ nối<br>tiếng Anh lớp 8.</h2><p>Luyện theo cấp độ, thi thử có giới hạn thời gian, xem giải thích và ôn câu sai. Tiến độ lưu trên trình duyệt này.</p></div>
<div class="stats"><div class="stat"><strong id="sessions">0</strong><span>Lượt hoàn thành</span></div><div class="stat"><strong id="best">—</strong><span>Điểm cao nhất</span></div><div class="stat"><strong id="mistakeCount">0</strong><span>Câu sai đã lưu</span></div></div>
<nav class="nav"><button class="tab active" onclick="showTab('practice',this)">📝 Luyện tập</button><button class="tab" onclick="showTab('exam',this)">⏱️ Thi thử</button><button class="tab" onclick="showTab('review',this)">🔁 Ôn câu sai</button><button class="tab" onclick="showTab('learn',this)">📚 Từ nối</button><button class="tab" onclick="showTab('progress',this)">📈 Tiến độ</button></nav>
<section id="practice" class="panel"><div class="row between"><div><h2 style="margin:0 0 4px">Chế độ luyện tập</h2><div class="small">Xem lời giải sau khi kiểm tra đáp án.</div></div><select class="select" id="level"><option value="all">Tất cả cấp độ</option><option value="easy">Dễ</option><option value="medium">Trung bình</option><option value="hard">Khó</option></select></div>
<div id="practiceArea"><div class="row between muted" style="margin-top:18px"><span id="counter"></span><span id="score">Đúng: 0</span></div><div class="progress"><div class="bar" id="bar"></div></div><div class="q" id="question"></div><div class="options" id="options"></div><div id="feedback"></div><div class="controls"><button class="btn primary" id="check" onclick="checkAnswer()">Kiểm tra đáp án</button><button class="btn" id="next" onclick="nextQuestion()" disabled>Câu tiếp theo →</button></div></div>
<div id="practiceResult" class="hidden"><div class="scorebig" id="finalScore"></div><p id="finalText"></p><button class="btn primary" onclick="startPractice()">Luyện lại</button></div></section>
<section id="exam" class="panel hidden"><h2>Thi thử có đồng hồ</h2><p class="muted">10 câu ngẫu nhiên trong 5 phút. Hết giờ, bài tự nộp.</p><div class="row"><button class="btn primary" id="startExam" onclick="startExam()">Bắt đầu thi</button><span class="pill" id="clock">05:00</span></div><div id="examArea" class="hidden"><div class="row between muted" style="margin-top:18px"><span id="examCounter"></span><span id="answered"></span></div><div class="progress"><div class="bar" id="examBar"></div></div><div class="q" id="examQuestion"></div><div class="options" id="examOptions"></div><div class="controls"><button class="btn" id="prev" onclick="moveExam(-1)">← Trước</button><button class="btn" onclick="moveExam(1)">Tiếp →</button><button class="btn primary" onclick="submitExam(false)">Nộp bài</button></div></div><div id="examResult" class="hidden"></div></section>
<section id="review" class="panel hidden"><div class="row between"><div><h2 style="margin:0">Ôn câu sai</h2><p class="muted">Các câu sai lưu trên trình duyệt hiện tại.</p></div><button class="btn" onclick="clearMistakes()">Xóa danh sách</button></div><div id="reviewList"></div></section>
<section id="learn" class="panel hidden"><h2>Ghi nhớ từ nối</h2><p class="muted">Xác định quan hệ giữa hai ý: kết quả, nguyên nhân, tương phản hay lựa chọn.</p>{% for w,m,e in connectors %}<div class="connector"><div class="word">{{w}}</div><div><div class="translation">{{m}}</div><div class="small">{{e}}</div></div></div>{% endfor %}</section>
<section id="progress" class="panel hidden"><h2>Lịch sử học tập</h2><p class="muted">Dữ liệu được lưu trên trình duyệt của thiết bị này.</p><div id="history"></div><div class="controls"><button class="btn" onclick="exportData()">Xuất dữ liệu</button><button class="btn" onclick="resetData()">Xóa toàn bộ tiến độ</button></div></section>
<p class="small">English Connectors 5.0 • Tiến độ không tự đồng bộ giữa các thiết bị.</p></main>
<script>
const BANK={{questions|tojson}}, KEY='ec_v5_progress';
let data=loadData(), qs=[], pos=0, points=0, chosen=null, checked=false;
let examQs=[], examAnswers={}, examPos=0, seconds=300, timer=null, examActive=false;
function loadData(){try{return JSON.parse(localStorage.getItem(KEY))||{sessions:0,best:0,history:[],mistakes:[]}}catch(e){return {sessions:0,best:0,history:[],mistakes:[]}}}
function saveData(){localStorage.setItem(KEY,JSON.stringify(data));updateStats()}
function updateStats(){document.getElementById('sessions').textContent=data.sessions;document.getElementById('best').textContent=data.sessions?data.best+'%':'—';document.getElementById('mistakeCount').textContent=data.mistakes.length}
function showTab(id,b){if(examActive&&id!=='exam'&&!confirm('Bài thi đang diễn ra. Rời trang thi?'))return;document.querySelectorAll('section.panel').forEach(s=>s.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(id==='review')renderReview();if(id==='progress')renderHistory()}
function shuffle(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startPractice(){let l=document.getElementById('level').value;qs=shuffle(BANK.filter(q=>l==='all'||q.level===l));pos=0;points=0;document.getElementById('practiceArea').classList.remove('hidden');document.getElementById('practiceResult').classList.add('hidden');renderPractice()}
function renderPractice(){if(pos>=qs.length){finishPractice();return}chosen=null;checked=false;let q=qs[pos],labels={easy:'Dễ',medium:'Trung bình',hard:'Khó'};document.getElementById('counter').textContent='Câu '+(pos+1)+'/'+qs.length+' · '+labels[q.level];document.getElementById('score').textContent='Đúng: '+points;document.getElementById('bar').style.width=(pos/qs.length*100)+'%';document.getElementById('question').textContent=q.q;document.getElementById('feedback').innerHTML='';document.getElementById('check').disabled=false;document.getElementById('next').disabled=true;let box=document.getElementById('options');box.innerHTML='';shuffle(q.options).forEach((o,i)=>{let b=document.createElement('button');b.className='opt';b.textContent=String.fromCharCode(65+i)+'. '+o;b.onclick=()=>{if(checked)return;chosen=o;document.querySelectorAll('#options .opt').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')};box.appendChild(b)})}
function addMistake(q,a){let key=q.q+'||'+q.answer,m=data.mistakes.find(x=>x.key===key);if(!m)data.mistakes.push({key:key,q:q.q,answer:q.answer,meaning:q.meaning,explain:q.explain,chosen:a||'(chưa chọn)',count:1});else{m.chosen=a||'(chưa chọn)';m.count=(m.count||1)+1}}
function checkAnswer(){if(!chosen){document.getElementById('feedback').innerHTML='<div class="feedback bad">Hãy chọn đáp án trước nhé.</div>';return}if(checked)return;checked=true;let q=qs[pos],ok=chosen.toLowerCase()===q.answer.toLowerCase();if(ok)points++;else addMistake(q,chosen);document.querySelectorAll('#options .opt').forEach(b=>{let v=b.textContent.slice(3);if(v.toLowerCase()===q.answer.toLowerCase())b.classList.add('correct');else if(v.toLowerCase()===chosen.toLowerCase())b.classList.add('wrong')});document.getElementById('feedback').innerHTML='<div class="feedback '+(ok?'good':'bad')+'"><b>'+(ok?'✓ Chính xác!':'✗ Chưa đúng.')+'</b><br>Đáp án: <b>'+q.answer+'</b><br>'+q.meaning+'<br><span class="small">'+q.explain+'</span></div>';document.getElementById('score').textContent='Đúng: '+points;document.getElementById('check').disabled=true;document.getElementById('next').disabled=false;saveData()}
function nextQuestion(){pos++;renderPractice()}
function finishPractice(){document.getElementById('practiceArea').classList.add('hidden');document.getElementById('practiceResult').classList.remove('hidden');document.getElementById('bar').style.width='100%';let pct=Math.round(points/qs.length*100);document.getElementById('finalScore').textContent=points+'/'+qs.length+' câu đúng ('+pct+'%)';document.getElementById('finalText').textContent=pct>=80?'Rất tốt! Hãy thử cấp độ khó hơn.':pct>=60?'Khá tốt! Hãy ôn lại câu sai.':'Tiếp tục luyện tập và xem mục Từ nối.';recordSession('Luyện tập',points,qs.length,pct)}
function recordSession(mode,s,n,pct){data.sessions++;data.best=Math.max(data.best,pct);data.history.unshift({date:new Date().toLocaleString('vi-VN'),mode:mode,score:s,total:n,pct:pct});data.history=data.history.slice(0,40);saveData()}
function startExam(){clearInterval(timer);examQs=shuffle(BANK).slice(0,10);examAnswers={};examPos=0;seconds=300;examActive=true;document.getElementById('examResult').classList.add('hidden');document.getElementById('examArea').classList.remove('hidden');document.getElementById('startExam').disabled=true;renderExam();updateClock();timer=setInterval(()=>{seconds--;updateClock();if(seconds<=0)submitExam(true)},1000)}
function updateClock(){document.getElementById('clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function renderExam(){let q=examQs[examPos];document.getElementById('examCounter').textContent='Câu '+(examPos+1)+'/10';document.getElementById('answered').textContent='Đã chọn: '+Object.keys(examAnswers).length+'/10';document.getElementById('examBar').style.width=((examPos+1)*10)+'%';document.getElementById('examQuestion').textContent=q.q;let box=document.getElementById('examOptions');box.innerHTML='';shuffle(q.options).forEach((o,i)=>{let b=document.createElement('button');b.className='opt'+(examAnswers[examPos]===o?' selected':'');b.textContent=String.fromCharCode(65+i)+'. '+o;b.onclick=()=>{examAnswers[examPos]=o;renderExam()};box.appendChild(b)});document.getElementById('prev').disabled=examPos===0}
function moveExam(d){examPos=Math.max(0,Math.min(9,examPos+d));renderExam()}
function submitExam(auto){if(!examActive)return;if(!auto&&!confirm('Bạn chắc chắn muốn nộp bài?'))return;examActive=false;clearInterval(timer);let s=0;examQs.forEach((q,i)=>{let a=examAnswers[i];if(a&&a.toLowerCase()===q.answer.toLowerCase())s++;else addMistake(q,a)});let pct=Math.round(s/10*100);recordSession(auto?'Thi thử (hết giờ)':'Thi thử',s,10,pct);document.getElementById('examArea').classList.add('hidden');document.getElementById('examResult').classList.remove('hidden');document.getElementById('examResult').innerHTML='<div class="scorebig">'+s+'/10 ('+pct+'%)</div><p>'+(auto?'Đã hết giờ. ':'')+'Bài thi đã được chấm. Vào mục Ôn câu sai để xem lại.</p><button class="btn primary" onclick="startExam()">Thi lại</button>';document.getElementById('startExam').disabled=false;document.getElementById('clock').textContent='Đã nộp'}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderReview(){let box=document.getElementById('reviewList');if(!data.mistakes.length){box.innerHTML='<div class="empty">Chưa có câu sai nào. Hãy làm bài luyện tập hoặc thi thử nhé!</div>';return}box.innerHTML=data.mistakes.map((m,i)=>'<div class="history-item"><div class="row between"><b>'+esc(h.mode)+'</b><span class="pill">'+h.pct+'%</span></div><div>'+h.score+'/'+h.total+' câu đúng</div><div class="small">'+esc(h.date)+'</div></div>').join('')}
function exportData(){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='english-connectors-progress.json';a.click();URL.revokeObjectURL(a.href)}
function resetData(){if(confirm('Xóa toàn bộ điểm, lịch sử và câu sai?')){data={sessions:0,best:0,history:[],mistakes:[]};saveData();renderHistory();renderReview()}}
document.getElementById('level').addEventListener('change',startPractice);updateStats();startPractice();
</script></body></html>"""

@app.route("/")
def home():
    return render_template_string(HTML, questions=BANK, connectors=CONNECTORS)

@app.route("/health")
def health():
    return jsonify({"status": "ok", "app": "English Connectors 5.0"})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)
 
